const $=s=>document.querySelector(s),fmt=n=>Number(n).toLocaleString('en-US');let page='overview';
const titles={overview:'Overview',districts:'District explorer',crops:'Production & losses',planner:'Support planner',insights:'Evidence assistant',method:'Data & methodology'};
function intro(k,t,p){return `<div class="eyebrow">${k}</div><div class="heading"><div><h1>${t}</h1><p>${p}</p></div><span class="tag">Historical evidence · 2017</span></div>`}
function bars(items){return items.map(([n,v])=>`<div class="barrow"><span>${n}</span><div class="track"><div class="fill" style="width:${v}%"></div></div><b>${v}%</b></div>`).join('')}
function card(label,value,note,highlight=false){return `<div class="card ${highlight?'highlight':''}"><label>${label}</label><div class="value">${value}</div><small>${note}</small></div>`}
function overview(){return intro('THE AGRICULTURAL PICTURE','Turn evidence into better support.','Explore farming constraints and understand where support gaps overlap.')+`<div class="cards">${card('Agricultural households','16,057','Practices-file sample')}${card('Received extension services','26.8%','4,310 / 16,057 households')}${card('Used irrigation','9.3%','1,495 / 16,057 households')}${card('Erosion + barriers + no extension','1,320','Historical outreach signal',true)}</div><div class="grid"><div class="panel"><h2>What limits soil protection?</h2><div class="sub">Among 3,075 households reporting barriers · multiple answers allowed</div>${bars([['Financial resources',60.6],['Knowledge',33.4],['Family labour',21.9],['Land tenure',18.2]])}<div class="callout"><strong>Different barriers call for different support.</strong>Explore reported needs before planning training, financial referrals, or further field assessment.</div></div><div class="panel"><h2>A gap worth investigating</h2><div class="sub">Reported erosion, protection barriers, and service coverage</div><div class="value">1,834</div><p>households reported increasing erosion and barriers to protecting their soil.</p><div class="value">72.0<span style="font-size:18px">%</span></div><p>of this group reported no extension service.</p><button class="primary" onclick="navigate('planner')">Explore support priorities →</button><div class="sub" style="margin-top:18px">An association, not proof that missing extension causes erosion.</div></div></div>`}
function districtTable(rows){return `<div class="tablewrap"><table><thead><tr><th>District</th><th>Sample households</th><th>Erosion + barrier</th><th>Sample share</th><th>Also no extension</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${r.district}</b></td><td>${fmt(r.sample_households)}</td><td>${r.erosion_and_barrier_n}</td><td><span class="mini"><i style="width:${r.erosion_and_barrier_pct*3}%"></i></span>${r.erosion_and_barrier_pct}%</td><td>${r.erosion_barrier_no_extension_n}</td></tr>`).join('')}</tbody></table></div>`}
function districts(){return intro('GEOGRAPHIC INSIGHTS','Understand the local picture.','Compare reported support gaps across districts in the historical sample.')+`<div class="panel"><div class="filters"><label>Find a district<input id="search" placeholder="Search district" oninput="filterDistricts()"></label><label>Sort by<select id="sort" onchange="filterDistricts()"><option value="share">Erosion and barrier share</option><option value="gap">No-extension overlap count</option><option value="name">District name</option></select></label><button class="outline" onclick="downloadCSV(DATA.districts,'district-evidence.csv')">Download CSV</button></div><div id="districtTable">${districtTable(DATA.districts)}</div><div class="callout">These are unweighted sample comparisons. They are not validated district prevalence rankings. Survey design and uncertainty require verification before operational use.</div></div>`}
function filterDistricts(){let q=$('#search').value.toLowerCase(),s=$('#sort').value;let a=DATA.districts.filter(r=>r.district.toLowerCase().includes(q));a.sort((a,b)=>s==='name'?a.district.localeCompare(b.district):s==='gap'?b.erosion_barrier_no_extension_n-a.erosion_barrier_no_extension_n:b.erosion_and_barrier_pct-a.erosion_and_barrier_pct);$('#districtTable').innerHTML=a.length?districtTable(a):'<div class="empty">No matching district.</div>'}
function crops(){return intro('PRODUCTION & POST-HARVEST','Follow the crop evidence.','Investigate reported losses across Seasons A and B, without treating records as households.')+`<div class="cards">${card('Usable crop-season records','63,979','Positive production; valid loss quantity')}${card('Records with reported loss','1,033','Across both seasons')}${card('Tomato positive-loss records','36.7%','139 / 379 usable tomato records',true)}${card('Tomato aggregate loss','3.83%','21,481 kg / 560,173.2 kg production')}</div><div class="panel" style="margin-top:22px"><h2>Reported losses by crop</h2><div class="sub">Crops with at least 100 usable records · sorted by recorded loss quantity</div><button class="outline" onclick="downloadCSV(DATA.crops,'crop-loss-evidence.csv')">Download CSV</button><div class="tablewrap"><table><thead><tr><th>Crop</th><th>Records</th><th>Positive loss</th><th>Loss quantity (kg)</th><th>Aggregate loss / production</th></tr></thead><tbody>${DATA.crops.map(r=>`<tr><td><b>${r.crop}</b></td><td>${fmt(r.records)}</td><td>${r.positive_loss_pct}%</td><td>${fmt(r.loss_kg)}</td><td>${r.aggregate_loss_pct}%</td></tr>`).join('')}</tbody></table></div><div class="callout">Households can contribute several crops and both seasons. Zero-loss reporting needs questionnaire validation. Reported losses do not identify the cause or establish the best storage or transport intervention.</div></div>`}
function planner(){return intro('OUTREACH PLANNING','Make priorities explainable.','Explore a capacity scenario for households reporting erosion and protection barriers.')+`<div class="grid"><div class="panel"><h2>Set your planning scenario</h2><div class="filters"><label>District<select id="district" onchange="plan()">${DATA.districts.map(r=>`<option>${r.district}</option>`).join('')}</select></label><label>Outreach capacity<input type="number" id="capacity" min="0" max="100000" value="30" oninput="plan()"></label></div><label><input type="checkbox" id="extension" checked onchange="plan()"> Prioritize households reporting no extension service</label><div class="callout"><strong>Transparent inclusion rule</strong>Reported increasing erosion AND reported soil-protection barriers. Optionally require reported absence of extension service.</div><p style="margin-top:20px">Historical sample scenario only. This does not identify current households, assign benefits, prescribe treatments, or predict yield improvements.</p></div><div class="panel" id="planResult"></div></div>`}
function plan(){const r=DATA.districts.find(r=>r.district===$('#district').value),n=$('#extension').checked?r.erosion_barrier_no_extension_n:r.erosion_and_barrier_n,capacity=Math.max(0,Math.floor(Number($('#capacity').value)||0)),covered=Math.min(n,capacity);$('#planResult').innerHTML=`<h2>${r.district} · historical scenario</h2><div class="sub">${fmt(r.sample_households)} sampled households in practices data</div><div class="value">${n}</div><p>sample households match the selected rule</p><div class="value">${covered} <span style="font-size:14px;color:#839077">/ ${n}</span></div><p>could be covered under the entered capacity; ${n-covered} remain outside this scenario.</p><div class="callout">Next step: validate current needs with local officers. Assess finance, knowledge, labour and tenure barriers before choosing referrals.</div>`}
function insights(){return intro('EVIDENCE ASSISTANT','Ask the data a better question.','Explore verified findings through a guided, local evidence lookup.')+`<div class="panel"><span class="tag">Verified lookup · live AI not connected</span><div class="chips">${['What limits soil protection?','Where are extension gaps?','What about tomato losses?','How many use irrigation?','What are the data limitations?'].map(t=>`<button onclick="answer(this.textContent)">${t}</button>`).join('')}</div><div class="answer" id="answer">Choose a question or ask about erosion, extension, finance, irrigation, or crop losses. Answers come from approved aggregate findings, without sending household data to an external service.</div><form class="ask" onsubmit="event.preventDefault();answer(document.querySelector('#question').value)"><input id="question" aria-label="Question about agricultural evidence" placeholder="Ask about the historical evidence…" required><button class="primary">Explore evidence →</button></form></div>`}
function answer(q){q=q.toLowerCase();let a;if(/limit|current|date|method/.test(q))a='The survey refers to 2016–2017. Findings are historical, unweighted sample descriptions. Independent extraction checks, survey weights, eligibility and uncertainty still require verification. Associations do not establish causes.';else if(/tomato|loss|storage|harvest/.test(q))a='139 of 379 usable tomato crop-season records (36.68%) reported losses. Recorded losses were 21,481 kg out of 560,173.2 kg production (3.83%). Records span Seasons A and B; households may repeat. Source: S8_A and S8_B, crop code 114.';else if(/extension|gap/.test(q))a='4,310 of 16,057 households (26.84%) reported extension service receipt. Among 1,834 households reporting increasing erosion and protection barriers, 1,320 reported no extension service. Source: S3 V6, deduplicated by household, joined one-to-one to S6.';else if(/irrig/.test(q))a='1,495 of 16,057 households (9.31%) reported irrigation use. This initial denominator includes all households in S6, not only crop-growing households. Low use alone does not establish irrigation need or feasibility. Source: S6 V29.';else if(/financ|loan|account/.test(q))a='8,352 of 16,057 households (52.01%) reported a financial institution account; 747 (4.65%) requested a loan. Non-application does not establish exclusion or unmet credit demand. Source: S4 V6 and V7.';else if(/soil|erosion|barrier/.test(q))a='Among 3,075 households reporting soil-protection barriers, 1,863 mentioned finance (60.59%), 1,026 knowledge (33.37%), 672 family labour (21.85%) and 559 tenure insecurity (18.18%). Multiple responses were allowed. Source: S6 V22, V23, V25 and V27.';else a='The verified evidence lookup cannot answer that question. Try soil protection, extension, finance, irrigation, or crop losses. Current conditions, treatment effects and yield predictions are not established by this prototype.';$('#answer').textContent=a+'\n\nReference period: 2016–2017. Unweighted historical sample evidence.'}
function method(){return intro('DATA & METHODOLOGY','Know what the evidence can say.','Transparent sources, reproducible calculations, and explicit limits.')+`<div class="panel prose"><h2>Sources and scope</h2><p>Sixteen supplied NISR SPSS files were inventoried. The first analytical release focuses on S0 (general information), S3 (extension), S4 (funding), S6 (practices), and S8_A/B (production and use). The practices file includes 16,057 distinct households. A custom reader extracted uncompressed SPSS records; independent verification in SPSS or pyreadstat remains pending.</p><h2>Joins and denominators</h2><p>S3 contains four rows per household. Extension receipt is consistent within households and was deduplicated before a one-to-one join to S6. Crop tables use crop-season records, not unique households. Missing or ineligible responses are not automatically treated as “No.” Increasing erosion excludes “Don’t know” in the yes/no indicator.</p><h2>Historical evidence, not current targeting</h2><p>The questionnaires refer to agricultural year 2016–2017. All displayed rates are unweighted sample descriptions. Segment weights exist, but the survey design and correct use of weights need confirmation. District comparisons have not been validated as national rankings. Yield differences and causal effects have not been estimated.</p><h2>AI and privacy</h2><p>This release uses deterministic evidence lookup, not a live language model. No API key or raw household records are included in the frontend. A future OpenAI integration should run server-side and explain approved aggregates. AI tools assisted coding, analysis and writing; participants remain responsible for verification and disclosure.</p><h2>Reproducibility and release</h2><p>Source tables, the analysis report, and setup instructions accompany the project. Verify dataset redistribution terms before publishing microdata. Validate calculations independently before competition submission.</p><a href="https://microdata.statistics.gov.rw/index.php/catalog" target="_blank" rel="noopener">NISR Microdata Catalogue ↗</a></div>`}
function navigate(p){page=p;location.hash=p;render()}function render(){page=titles[location.hash.slice(1)]?location.hash.slice(1):page;$('#crumb').textContent=titles[page];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#content').innerHTML=({overview,districts,crops,planner,insights,method})[page]();if(page==='planner')plan()}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.page));window.onhashchange=render;
function save(text,name,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function downloadCSV(rows,name){const keys=Object.keys(rows[0]),esc=v=>'"'+String(v).replaceAll('"','""')+'"';save([keys.map(esc).join(','),...rows.map(r=>keys.map(k=>esc(r[k])).join(','))].join('\r\n'),name,'text/csv')}
$('#export').onclick=()=>{let text='AgriInsight Rwanda — historical evidence briefing\nReference period: 2016–2017\n\n16,057 households in practices sample.\n1,834 report increasing erosion and protection barriers; 1,320 also report no extension service.\nUnweighted sample descriptions, not current conditions or causal effects.\n';if(page==='planner')text+='\nSelected planning scenario:\n'+$('#planResult').innerText;else text+='\n'+$('#content').innerText;save(text,'agriinsight-briefing.txt','text/plain')};render();
